svg.script:

document.addEventListener("DOMContentLoaded", () => {
  const button = document.getElementById("launch-trigger");

  if (button) {
    button.addEventListener("click", () => {
      // REPLACE WITH YOUR ACTUAL GITHUB RAW URL
      const gitHubRawUrl = "https://raw.githubusercontent.com/zaka13X/zaka13X/refs/heads/main/games/123.html";

      button.textContent = "Loading...";
      button.disabled = true;

      fetch(gitHubRawUrl)
        .then(response => {
          if (!response.ok) throw new Error(`HTTP error! Status: ${response.status}`);
          return response.text();
        })
        .then(htmlString => {
          // 1. Convert the plain text string into a formal binary data blob
          const blob = new Blob([htmlString], { type: "text/html;charset=utf-8" });

          // 2. Create a secure, temporary local URL pointer for that blob data
          const blobUrl = URL.createObjectURL(blob);

          // 3. Open the blob directly in a new tab (bypasses about:blank restrictions)
          const newTab = window.open(blobUrl, "_blank");

          if (!newTab) {
            alert("Popup blocker prevented opening the tab. Please allow popups!");
          }
        })
        .catch(error => {
          console.error("Failed to render window:", error);
          alert("Error fetching document.");
        })
        .finally(() => {
          button.textContent = "Launch";
          button.disabled = false;
        });
    });
  }
});
